    op = rule["op"]
    if op == "all":
        return all(_evaluate(child, document) for child in rule["rules"])
    if op == "any":
        return any(_evaluate(child, document) for child in rule["rules"])
    if op == "not":
        return not _evaluate(rule["rule"], document)
    value = _value(document, rule["path"])
    if op == "exists":
        return value is not _MISSING
    if op == "eq":
        return type(value) is type(rule["value"]) and value == rule["value"]
    return type(value) is int and rule["low"] <= value <= rule["high"]

def evaluate(rule, document):
    validate_rule(rule)
    if type(document) is not dict:
        raise ValueError("document:object_required")
    return _evaluate(rule, document)

"""Current v2 evaluator for the finite rule migration API."""
def evaluate_v2(rule, document):
    kind = rule["kind"]
    if kind == "all":
        return all(evaluate_v2(child, document) for child in rule["children"])
    if kind == "any":
        return any(evaluate_v2(child, document) for child in rule["children"])
    if kind == "not":
        return not evaluate_v2(rule["child"], document)
    value = document
    for key in rule["path"]:
        value = value.get(key) if isinstance(value, dict) else None
    if rule["test"] == "exists":
        return value is not None
    if rule["test"] == "eq":
        return value == rule.get("value")
    return isinstance(value, int) and rule["bounds"][0] <= value <= rule["bounds"][1]

