        # exists returns true if the key exists, even if the value is None (null)
        return value is not None
    if rule["test"] == "eq":
        # eq is type-strict: null == null is true, but missing (None) == null is false
        return value == rule.get("value")
    if rule["test"] == "between":
        return isinstance(value, int) and rule["bounds"][0] <= value <= rule["bounds"][1]
    return False

