"""
Canonical v2 rule evaluator.

Input is a canonical v2 rule tree (produced by migrate_v1_to_v2), document, and context.
Evaluates the rule against the document and returns {"rule": <v2-rule>, "results": [bool, ...]}.

v2 structure:
  - {kind: "all"|"any", children: [<v2-rule>, ...]}
  - {kind: "not", child: <v2-rule>}
  - {kind: "predicate", path: [<str>, ...], test: "eq"|"exists"|"between", value?}

Depth validated at caller.
"""

import copy


def _validate_path_segments(path, max_depth=4):
    """Check path segments are valid and depth is within bounds."""
    if not isinstance(path, list):
        return f"invalid_v2"
    if len(path) > max_depth:
        return f"invalid_v2"
    for seg in path:
        if not isinstance(seg, str):
            return f"invalid_v2"
        if not seg or not all(c in 'abcdefghijklmnopqrstuvwxyz0123456789_' for c in seg):
            return f"invalid_v2"
    return None


def _validate_child(child, index, depth=1, max_depth=4):
    """Validate a child rule and return error if invalid."""
    if not isinstance(child, dict):
        return f"invalid_v2"
    if 'kind' not in child:
        return f"invalid_v2"
    if child['kind'] == 'predicate':
        if 'path' not in child:
            return f"invalid_v2"
        if _validate_path_segments(child['path'], max_depth - depth) is None:
            return None
        if 'test' not in child:
            return f"invalid_v2"
        if child['test'] not in ('eq', 'exists', 'between'):
            return f"invalid_v2"
        if child['test'] == 'eq' and 'value' not in child:
            return f"invalid_v2"
    elif child['kind'] == 'exists':
        # exists has no additional fields in v2
        pass
    elif child['kind'] == 'not':
        if 'child' not in child:
            return f"invalid_v2"
        if _validate_child(child['child'], index + 1, depth + 1, max_depth) is None:
            return None
    elif child['kind'] == 'all':
        if 'children' not in child:
            return f"invalid_v2"
        if not isinstance(child['children'], list) or len(child['children']) < 1 or len(child['children']) > 4:
            return f"invalid_v2"
        for i, c in enumerate(child['children']):
            if _validate_child(c, i, depth + 1, max_depth) is None:
                return None
    elif child['kind'] == 'any':
        if 'children' not in child:
            return f"invalid_v2"
        if not isinstance(child['children'], list) or len(child['children']) < 1 or len(child['children']) > 4:
            return f"invalid_v2"
        for i, c in enumerate(child['children']):
            if _validate_child(c, i, depth + 1, max_depth) is None:
                return None
    else:
        return f"invalid_v2"
    return None


def evaluate_predicate(rule, document, context=None):
    """Evaluate a predicate rule."""
    path = rule['path']
    test = rule['test']

    # Navigate path
    current = document
    for seg in path:
        if current is None:
            return False
        if seg not in current:
            return False
        current = current[seg]

    if test == 'eq':
        value = rule.get('value')
        return current == value
    elif test == 'exists':
        return True  # exists is always true if path exists
    elif test == 'between':
        bounds = rule['bounds']
        if not isinstance(bounds, list) or len(bounds) != 2:
            return False
        low, high = bounds[0], bounds[1]
        if not isinstance(current, int):
            return False
        return low <= current <= high
    return False


def evaluate_rule(rule, document, context=None):
    """Evaluate a v2 rule against a document."""
    kind = rule['kind']

    if kind == 'predicate':
        return evaluate_predicate(rule, document, context)
    elif kind == 'not':
        child = rule['child']
        return not evaluate_rule(child, document, context)
    elif kind == 'all':
        children = rule['children']
        return all(evaluate_rule(child, document, context) for child in children)
    elif kind == 'any':
        children = rule['children']
        return any(evaluate_rule(child, document, context) for child in children)
    return False


def evaluate_v2(rule, document):
    """
    Evaluate a canonical v2 rule tree against a document.

    Args:
        rule: Canonical v2 rule tree (from migrate_v1_to_v2 output)
        document: JSON object to evaluate against

    Returns:
        {"rule": rule, "results": [bool, ...]}

    Raises:
        ValueError: If rule or document has invalid v2 structure
    """
    # Validate document is an object
    if not isinstance(document, dict):
        raise ValueError("$.document:object_required")

    # Validate rule structure
    if not isinstance(rule, dict):
        raise ValueError("$.rule:object_required")
    if 'kind' not in rule:
        raise ValueError("$.rule:missing")

    max_depth = 4
    max_nodes = 16

    # Validate rule depth and node count
    def count_nodes(rule, depth=1):
        count = 1
        if depth >= max_depth:
            return count
        if rule['kind'] in ('all', 'any'):
            for child in rule.get('children', []):
                count += count_nodes(child, depth + 1)
        elif rule['kind'] == 'not':
            count += count_nodes(rule['child'], depth + 1)
        return count

    # Check node count
    if count_nodes(rule) > max_nodes:
        raise ValueError("$.rule:node_limit")

    # Validate entire rule tree
    if _validate_child(rule, 0, 1, max_depth) is None:
        raise ValueError("$.rule:invalid_v2")

    # Evaluate
    results = evaluate_rule(rule, document)

    return {"rule": rule, "results": [results]}

