def migrate_v1_to_v2(rule):
    """Convert v1 rule to v2, validating and preserving error locations."""
    # Validate the input rule first
    try:
        validate_rule(rule)
    except ValueError as e:
        raise  # Re-raise the validation error

    def convert(node, depth=0):
        # Check depth limit
        if depth > 4:
            raise ValueError("$:depth_limit")

        op = node["op"]

        if op in ("all", "any"):
            # Validate children
            if "rules" not in node or not isinstance(node["rules"], list):
                raise ValueError(f"${node.get('path', '$')}:rules:missing")
            if len(node["rules"]) < 1 or len(node["rules"]) > 4:
                raise ValueError(f"${node.get('path', '$')}:rule_list_required")

            children = [convert(child, depth + 1) for child in node["rules"]]
            return {"kind": op, "children": children}

        elif op == "not":
            # Validate single child
            if "rule" not in node:
                raise ValueError(f"${node.get('path', '$')}.rule:missing")
            child = convert(node["rule"], depth + 1)
            return {"kind": "not", "child": child}

        else:
            # Predicate operations
            if "path" not in node:
                raise ValueError(f"${node.get('path', '$')}:path:missing")

            try:
                path_list = node["path"].split(".")
            except:
                raise ValueError(f"${node.get('path', '$')}:invalid_path")

            if len(path_list) < 1 or len(path_list) > 4:
                raise ValueError(f"${node.get('path', '$')}:invalid_path")

            result = {"kind": "predicate", "path": path_list, "test": op}

            if op == "eq":
