                    raise ValueError(f"${node.get('path', '$')}.low:missing")
                if "high" not in node:
                    raise ValueError(f"${node.get('path', '$')}.high:missing")
                result["bounds"] = [node["low"], node["high"]]

            elif op == "exists":
                # exists has no additional fields to validate
                pass

            else:
                # Unknown op
                raise ValueError(f"${node.get('path', '$')}:op:unknown")

            return result

    # Create a deep copy to avoid mutating the input
    rule_copy = copy.deepcopy(rule)
