import copy
from rule_v1 import validate_rule, validate_node_depth, validate_node_children


def migrate_v1_to_v2(rule):
    """Migrate v1 rule to v2, with full validation."""
    # Validate v1 rule first
    validate_rule(rule)

    # Deep copy to ensure no mutation of input
    rule_copy = copy.deepcopy(rule)

    def validate_and_convert(node, path_prefix="$"):
        """Validate node and convert to v2."""
        if not isinstance(node, dict):
            raise ValueError(f"{path_prefix}:object_required")

        if "op" not in node:
            raise ValueError(f"{path_prefix}.op:missing")

        op = node["op"]

        if op == "all":
            if "rules" not in node:
                raise ValueError(f"{path_prefix}.rules:missing")
            if not isinstance(node["rules"], list):
                raise ValueError(f"{path_prefix}.rules:object_required")
            if len(node["rules"]) == 0:
                raise ValueError(f"{path_prefix}.rules:rule_list_required")
            children = []
            for i, child in enumerate(node["rules"]):
                child_path = f"{path_prefix}.rules[{i}]"
                children.append(validate_and_convert(child, child_path))
            return {"kind": "all", "children": children}

        elif op == "any":
            if "rules" not in node:
                raise ValueError(f"{path_prefix}.rules:missing")
            if not isinstance(node["rules"], list):
                raise ValueError(f"{path_prefix}.rules:object_required")
            if len(node["rules"]) == 0:
                raise ValueError(f"{path_prefix}.rules:rule_list_required")
            children = []
            for i, child in enumerate(node["rules"]):
                child_path = f"{path_prefix}.rules[{i}]"
                children.append(validate_and_convert(child, child_path))
            return {"kind": "any", "children": children}

        elif op == "not":
            if "rule" not in node:
                raise ValueError(f"{path_prefix}.rule:missing")
            child_path = f"{path_prefix}.rule"
            child = validate_and_convert(node["rule"], child_path)
            return {"kind": "not", "child": child}

        else:
            # Leaf predicate: eq, exists, between
            if "path" not in node:
                raise ValueError(f"{path_prefix}.path:missing")
            if not isinstance(node["path"], str):
                raise ValueError(f"{path_prefix}.path:object_required")
            if len(node["path"]) == 0:
                raise ValueError(f"{path_prefix}.path:invalid_path")

            segments = node["path"].split(".")
            if not all(s.isidentifier() for s in segments):
                raise ValueError(f"{path_prefix}.path:invalid_path")

            result = {"kind": "predicate", "path": segments, "test": op}

            if op == "eq":
                if "value" not in node:
                    raise ValueError(f"{path_prefix}.value:missing")
                result["value"] = node["value"]

            elif op == "between":
                if "low" not in node:
                    raise ValueError(f"{path_prefix}.low:missing")
                if "high" not in node:
                    raise ValueError(f"{path_prefix}.high:missing")
                if not isinstance(node["low"], int):
                    raise ValueError(f"{path_prefix}.low:integer_required")
                if not isinstance(node["high"], int):
                    raise ValueError(f"{path_prefix}.high:integer_required")
                if node["low"] > node["high"]:
                    raise ValueError(f"{path_prefix}.high:invalid_range")
                result["bounds"] = [node["low"], node["high"]]

            return result

    return validate_and_convert(rule_copy)

