"""
Canonical v2 rule evaluator.

Input is a canonical v2 rule tree (produced by migrate_v1_to_v2), document, and context.
Evaluates the rule against the document and returns {"rule": <v2-rule>, "results": [bool, ...]}.

v2 structure:
  - {kind: "all"|"any", children: [<v2-rule>, ...]}
  - {kind: "not", child: <v2-rule>}
  - {kind: "predicate", path: [<str>, ...], test: "eq"|"exists"|"between", value?}

Depth validated at caller.
"""

import copy


def _validate_path_segments(path, max_depth=4):
    """Check path segments are valid and depth is within bounds."""
    if not isinstance(path, list):
        return f"invalid_v2"
    if len(path) > max_depth:
        return f"invalid_v2"
    for seg in path:
        if not isinstance(seg, str):
            return f"invalid_v2"
        if not seg or not all(c in 'abcdefghijklmnopqrstuvwxyz0123456789_' for c in seg):
            return f"invalid_v2"
    return None


def _validate_child(child, index, depth=1, max_depth=4):
    """Validate a child rule and return error if invalid."""
    if not isinstance(child, dict):
        return f"invalid_v2"
    if 'kind' not in child:
        return f"invalid_v2"
    if child['kind'] == 'predicate':
        if 'path' not in child:
            return f"invalid_v2"
        if _validate_path_segments(child['path'], max_depth - depth) is None:
            return None
        if 'test' not in child:
            return f"invalid_v2"
        if child['test'] not in ('eq', 'exists', 'between'):
            return f"invalid_v2"
        if child['test'] == 'eq' and 'value' not in child:
            return f"invalid_v2"
    elif child['kind'] == 'exists':
        # exists has no additional fields in v2
        pass
    elif child['kind'] == 'not':
        if 'child' not in child:
            return f"invalid_v2"
        if _validate_child(child['child'], index + 1, depth + 1, max_depth) is None:
            return None
    elif child['kind'] == 'all':
        if 'children' not in child:
            return f"invalid_v2"
        if not isinstance(child['children'], list) or len(child['children']) < 1 or len(child['children']) > 4:
            return f"invalid_v2"
        for i, c in enumerate(child['children']):
            if _validate_child(c, i, depth + 1, max_depth) is None:
                return None
    elif child['kind'] == 'any':
        if 'children' not in child:
            return f"invalid_v2"
