"""Current v2 evaluator for the finite rule migration API."""


def evaluate_v2(rule, document):
    # Validate v2 structure
    if not isinstance(rule, dict):
        raise ValueError("$:invalid_v2")
    if "kind" not in rule:
        raise ValueError("$:invalid_v2")
    if "path" not in rule:
        raise ValueError("$:invalid_v2")
    if not isinstance(rule["path"], list):
        raise ValueError("$:invalid_v2")

    kind = rule["kind"]

    if kind == "all":
        if "children" not in rule:
            raise ValueError("$:invalid_v2")
        if not isinstance(rule["children"], list) or len(rule["children"]) == 0:
            raise ValueError("$:invalid_v2")
        if len(rule["children"]) > 4:
            raise ValueError("$:invalid_v2")
        return all(evaluate_v2(child, document) for child in rule["children"])

    if kind == "any":
        if "children" not in rule:
            raise ValueError("$:invalid_v2")
        if not isinstance(rule["children"], list) or len(rule["children"]) == 0:
            raise ValueError("$:invalid_v2")
        if len(rule["children"]) > 4:
            raise ValueError("$:invalid_v2")
        return any(evaluate_v2(child, document) for child in rule["children"])

    if kind == "not":
        if "child" not in rule:
            raise ValueError("$:invalid_v2")
        return not evaluate_v2(rule["child"], document)

    # Predicate nodes
    if kind == "predicate":
        if "test" not in rule:
            raise ValueError("$:invalid_v2")
        if rule["test"] == "exists":
            value = document
            for key in rule["path"]:
                if not isinstance(value, dict) or key not in value:
                    return False
                value = value[key]
            # exists returns true if path exists, even if value is null
            return True
        elif rule["test"] == "eq":
            # Get the value at the path
            value = document
            for key in rule["path"]:
                if not isinstance(value, dict) or key not in value:
                    value = None
                    break
                value = value[key]
            # eq compares strictly, including null vs null
            eq_value = rule.get("value")
            if eq_value is None:
                return value is None
            return value == eq_value
        elif rule["test"] == "between":
            if "bounds" not in rule:
                raise ValueError("$:invalid_v2")
            if not isinstance(rule["bounds"], list) or len(rule["bounds"]) != 2:
                raise ValueError("$:invalid_v2")
            low, high = rule["bounds"]
            # Get the value at the path
            value = document
            for key in rule["path"]:
                if not isinstance(value, dict) or key not in value:
                    value = None
                    break
                value = value[key]
            # between only accepts actual ints
            if not isinstance(value, int) or isinstance(value, bool):
                return False
            return low <= value <= high
        else:
            raise ValueError("$:invalid_v2")

    raise ValueError("$:invalid_v2")

